-- No request()/response() hook: keep the load generator on wrk's native fast path.
-- Method/body are set once, before the request is pre-generated by wrk.
local scenario = os.getenv("BENCH_SCENARIO") or "plaintext"
wrk.headers["Accept-Encoding"] = "identity"
wrk.headers["Connection"] = "keep-alive"
if scenario == "echo" then
    wrk.method = "POST"
    wrk.headers["Content-Type"] = "application/json"
    wrk.body = '{"message":"benchmark","number":42}'
end

function done(summary, latency, requests)
    assert(summary.expected_status == 200, "This benchmark requires the native strict HTTP 200 wrk build")
    local function number(value)
        if value ~= value or value == math.huge or value == -math.huge then return "null" end
        return string.format("%.6f", value)
    end
    local function percentile(p)
        if summary.requests == 0 then return "null" end
        return number(latency:percentile(p))
    end
    local result = '{"expected_status":' .. number(summary.expected_status)
        .. ',"duration_us":' .. number(summary.duration)
        .. ',"requests":' .. number(summary.requests)
        .. ',"bytes":' .. number(summary.bytes)
        .. ',"latency_us":{"p50":' .. percentile(50)
        .. ',"p95":' .. percentile(95) .. ',"p99":' .. percentile(99)
        .. ',"mean":' .. number(latency.mean) .. ',"max":' .. number(latency.max) .. '}'
        .. ',"errors":{"connect":' .. number(summary.errors.connect)
        .. ',"read":' .. number(summary.errors.read) .. ',"write":' .. number(summary.errors.write)
        .. ',"status":' .. number(summary.errors.status) .. ',"timeout":' .. number(summary.errors.timeout) .. '}}'
    io.write("HXWELL_BENCH_JSON " .. result .. "\n")
end
